# Generated by cdt init powershell. Only this integration source is evaluated.
if ($PSVersionTable.PSVersion.Major -lt 7) {
    throw 'cdt requires PowerShell 7 or newer.'
}
$cdtApplication = Get-Command cdt.exe, cdt -CommandType Application -ErrorAction SilentlyContinue |
    Select-Object -First 1
if (-not $cdtApplication) {
    throw 'cdt executable was not found on PATH.'
}
$cdtModule = New-Module -Name CdtIntegration -ArgumentList $cdtApplication.Source -ScriptBlock {
    param([string] $Executable)
    $script:Executable = $Executable

    function Get-CdtArguments($Invocation, [string[]] $Values) {
        # PowerShell consumes an unquoted -- before invoking a function.
        # Recover its position from syntax only; never evaluate AST values.
        $tokens = $null
        $errors = $null
        $ast = [Management.Automation.Language.Parser]::ParseInput(
            $Invocation.Statement, [ref] $tokens, [ref] $errors)
        $command = $ast.Find({ param($node)
            $node -is [Management.Automation.Language.CommandAst]
        }, $true)
        $index = 0
        $splatted = $false
        foreach ($element in $command.CommandElements | Select-Object -Skip 1) {
            if ($element -is [Management.Automation.Language.CommandParameterAst] -and
                $element.Extent.Text -eq '--') {
                if ($splatted) { throw "use a quoted '--' when splatting arguments" }
                $result = [Collections.Generic.List[string]]::new()
                $result.AddRange($Values)
                $result.Insert($index, '--')
                return ,$result.ToArray()
            }
            if ($element -is [Management.Automation.Language.VariableExpressionAst] -and $element.Splatted) {
                $splatted = $true
            }
            $index++
        }
        return ,$Values
    }

    function Get-CdtResponse([string] $Operation, [string[]] $Tags) {
        $json = & $script:Executable $Operation -- @Tags
        if ($LASTEXITCODE -ne 0) {
            throw 'registry query failed'
        }
        $response = ($json -join "`n") | ConvertFrom-Json -ErrorAction Stop
        if ($response.version -ne 1 -or $null -eq $response.entries) {
            throw 'unsupported shell protocol'
        }
        return $response
    }

    function Get-CdtLabel($Entry) {
        $path = $Entry.path -replace '\p{Cc}', ([string][char]0xfffd)
        return "$path  [$($Entry.tags -join ', ')]"
    }

    function Get-CdtMenuAction([ConsoleKeyInfo] $Key) {
        if ($Key.Key -eq [ConsoleKey]::Enter) { return 'accept' }
        if ($Key.Key -eq [ConsoleKey]::Escape -or
            (($Key.Modifiers -band [ConsoleModifiers]::Control) -and
             $Key.Key -in @([ConsoleKey]::C, [ConsoleKey]::G))) { return 'cancel' }
        if ($Key.Key -eq [ConsoleKey]::UpArrow -or
            ($Key.Key -eq [ConsoleKey]::Tab -and
             ($Key.Modifiers -band [ConsoleModifiers]::Shift))) { return 'previous' }
        if ($Key.Key -in @([ConsoleKey]::DownArrow, [ConsoleKey]::Tab)) { return 'next' }
        return 'ignore'
    }

    function Select-CdtCandidate([object[]] $Entries) {
        for ($i = 0; $i -lt $Entries.Count; $i++) {
            [Console]::Error.WriteLine("  $($i + 1)  $(Get-CdtLabel $Entries[$i])")
        }
        $index = 0
        $previousMode = [Console]::TreatControlCAsInput
        try {
            [Console]::TreatControlCAsInput = $true
            while ($true) {
                [Console]::Error.Write("`rcdt> $($index + 1)/$($Entries.Count)  ")
                switch (Get-CdtMenuAction ([Console]::ReadKey($true))) {
                    'accept' { return $Entries[$index] }
                    'cancel' { return $null }
                    'next' { $index = ($index + 1) % $Entries.Count }
                    'previous' { $index = ($index + $Entries.Count - 1) % $Entries.Count }
                }
            }
        } finally {
            [Console]::TreatControlCAsInput = $previousMode
            [Console]::Error.WriteLine()
        }
    }

    function cdt {
        try {
            $arguments = Get-CdtArguments $MyInvocation ([string[]] @($args))
        } catch {
            [Console]::Error.WriteLine("cdt: $($_.Exception.Message)")
            $global:LASTEXITCODE = 1
            return
        }
        $ended = $false
        $mutates = $false
        $native = $arguments.Count -eq 0 -or
            ($arguments.Count -eq 2 -and $arguments[0] -eq 'init')
        $tags = [Collections.Generic.List[string]]::new()
        foreach ($argument in $arguments) {
            if (-not $ended -and $argument -eq '--') {
                $ended = $true
            } elseif (-not $ended -and $argument.StartsWith('-') -and $argument -ne '-') {
                $native = $true
                if ($argument -in @('--add', '--delete', '--remove', '--move') -or
                    ($argument -notlike '--*' -and $argument.Split('p')[0] -match '[adr]')) {
                    $mutates = $true
                }
            } else {
                $tags.Add($argument)
            }
        }
        if ($native) {
            if ($mutates -and (Get-Location).Provider.Name -ne 'FileSystem') {
                [Console]::Error.WriteLine('cdt: directory changes require a filesystem location')
                $global:LASTEXITCODE = 1
                return
            }
            & $script:Executable @arguments
            $global:LASTEXITCODE = $LASTEXITCODE
            return
        }
        try {
            if ((Get-Location).Provider.Name -ne 'FileSystem') {
                throw 'directory jumping requires a filesystem location'
            }
            $response = Get-CdtResponse '__query' $tags.ToArray()
            $entries = @($response.entries)
            if ($entries.Count -eq 0) {
                throw 'no matching directory'
            }
            $interactive = -not [Console]::IsInputRedirected -and
                -not [Console]::IsOutputRedirected -and
                -not ([Environment]::GetCommandLineArgs() -contains '-NonInteractive')
            $selected = $entries[0]
            if ($entries.Count -gt 1) {
                if (-not $interactive) {
                    [Console]::Error.WriteLine('cdt: ambiguous query; use -l or add tags')
                    $global:LASTEXITCODE = 2
                    return
                }
                $selected = Select-CdtCandidate $entries
                if ($null -eq $selected) {
                    [Console]::Error.WriteLine('cdt: cancelled; directory unchanged')
                    $global:LASTEXITCODE = 130
                    return
                }
            }
            Set-Location -LiteralPath $selected.path -ErrorAction Stop
            if ($interactive) {
                [Console]::Error.WriteLine("cdt: entered $(Get-CdtLabel $selected)")
            }
            $global:LASTEXITCODE = 0
        } catch {
            [Console]::Error.WriteLine("cdt: $($_.Exception.Message)")
            $global:LASTEXITCODE = 1
        }
    }

    Register-ArgumentCompleter -CommandName cdt -ScriptBlock {
        param($wordToComplete, $commandAst, $cursorPosition)
        # Never evaluate the AST. Only literal argument values constrain tags.
        $before = [Collections.Generic.List[string]]::new()
        foreach ($element in $commandAst.CommandElements | Select-Object -Skip 1) {
            if ($element.Extent.StartOffset -ge $cursorPosition - $wordToComplete.Length) { break }
            if ($element -is [Management.Automation.Language.StringConstantExpressionAst]) {
                $before.Add($element.Value)
            } elseif ($element -is [Management.Automation.Language.CommandParameterAst]) {
                $before.Add($element.Extent.Text)
            } else {
                return
            }
        }
        $tags = [Collections.Generic.List[string]]::new()
        $expectPath = $false
        $ended = $false
        $moving = $false
        foreach ($value in $before) {
            if ($expectPath) { $expectPath = $false; continue }
            if (-not $ended -and $value -eq '--') { $ended = $true; continue }
            if (-not $ended -and $value -eq '--tags') { return }
            if (-not $ended -and $value -eq '--move') { $moving = $true; continue }
            if (-not $ended -and ($value -eq '--path' -or $value -match '^-[adrl]*p$')) {
                $expectPath = $true
                continue
            }
            if (-not $ended -and $value.StartsWith('-')) { continue }
            $tags.Add($value)
        }
        $prefix = $wordToComplete
        $current = $commandAst.CommandElements | Where-Object {
            $_.Extent.StartOffset -ge $cursorPosition - $wordToComplete.Length
        } | Select-Object -First 1
        if ($current -is [Management.Automation.Language.StringConstantExpressionAst]) {
            $prefix = $current.Value
        } elseif ($wordToComplete) {
            return
        }
        if ($moving -and $tags.Count -ge 2) { return }
        if ($expectPath -or $moving) {
            $path = [Environment]::ExpandEnvironmentVariables($prefix)
            if ($path.StartsWith('~')) { $path = $HOME + $path.Substring(1) }
            if ($moving -and $tags.Count -eq 0 -and (Get-Location).Provider.Name -eq 'FileSystem') {
                $absolute = if ([IO.Path]::IsPathRooted($path)) { $path } else {
                    Join-Path (Get-Location).ProviderPath $path
                }
                try {
                    $response = Get-CdtResponse '__paths' @()
                    foreach ($entry in $response.entries) {
                        if (-not [IO.Directory]::Exists($entry.path) -and
                            $entry.path.StartsWith($absolute, [StringComparison]::OrdinalIgnoreCase)) {
                            $quoted = "'" + $entry.path.Replace("'", "''") + "'"
                            [Management.Automation.CompletionResult]::new($quoted, $entry.path, 'ProviderContainer', $entry.path)
                        }
                    }
                } catch {
                    # A damaged registry must not interrupt ordinary path completion.
                }
            }
            if (-not $path -or $path.EndsWith([string][IO.Path]::DirectorySeparatorChar)) {
                $parent = $path
                $leaf = ''
            } else {
                $parent = Split-Path -Path $path -Parent
                $leaf = Split-Path -Path $path -Leaf
            }
            if (-not $parent) { $parent = '.' }
            Get-ChildItem -LiteralPath $parent -Directory -ErrorAction SilentlyContinue |
                Where-Object { $_.Name.StartsWith($leaf, [StringComparison]::OrdinalIgnoreCase) } |
                ForEach-Object {
                    $quoted = "'" + $_.FullName.Replace("'", "''") + "'"
                    [Management.Automation.CompletionResult]::new($quoted, $_.Name, 'ProviderContainer', $_.FullName)
                }
            return
        }
        try {
            $response = Get-CdtResponse '__complete' $tags.ToArray()
            foreach ($entry in $response.entries) {
                if ($entry.path.StartsWith($prefix, [StringComparison]::Ordinal) -and
                    -not $tags.Contains($entry.path)) {
                    $quoted = "'" + $entry.path.Replace("'", "''") + "'"
                    [Management.Automation.CompletionResult]::new($quoted, $entry.path, 'ParameterValue', $entry.path)
                }
            }
        } catch {
            # Completion must not print errors into the editing buffer.
        }
    }
    Export-ModuleMember -Function cdt
}
Import-Module $cdtModule -Global -Force
Remove-Variable cdtApplication, cdtModule
